<?php

declare(strict_types=1);
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>FourBag League Operations</title>
<style>
:root{--bg:#efe7d8;--paper:#fffaf0;--ink:#191714;--muted:#71685e;--red:#a43a2d;--green:#315844;--line:#d8ccb9;--shadow:0 12px 34px rgba(40,30,20,.1)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}.top{position:sticky;top:0;z-index:5;background:rgba(255,250,240,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.topin{max-width:1250px;margin:auto;padding:15px 20px;display:flex;justify-content:space-between;gap:14px;align-items:center}.brand{font:800 26px Georgia,serif}.brand small{display:block;font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:.16em;color:var(--red);margin-top:3px}.wrap{max-width:1250px;margin:auto;padding:22px 20px 60px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:15px}.card{grid-column:span 12;background:var(--paper);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow);padding:18px}.s8{grid-column:span 8}.s7{grid-column:span 7}.s6{grid-column:span 6}.s5{grid-column:span 5}.s4{grid-column:span 4}h1,h2{font-family:Georgia,serif;margin:0 0 12px}h1{font-size:28px}h2{font-size:21px}h3{font-size:11px;text-transform:uppercase;letter-spacing:.11em;color:var(--green);margin:0 0 8px}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.split{display:flex;justify-content:space-between;gap:12px;align-items:center}.btn{border:1px solid var(--line);border-radius:9px;background:#fffdf8;color:var(--ink);padding:9px 12px;font-weight:800;cursor:pointer}.btn.red{background:var(--red);border-color:var(--red);color:#fff}.btn.green{background:var(--green);border-color:var(--green);color:#fff}input,select{border:1px solid #cdbfa9;border-radius:9px;background:#fffdf8;padding:9px 10px;max-width:100%}.key{width:230px}.muted{color:var(--muted)}.small{font-size:12px}.badge{display:inline-block;padding:5px 8px;border-radius:999px;background:#eee2cf;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.badge.green{background:#dfe9e1;color:#214331}.badge.red{background:#f2dedb;color:#7c291f}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.kpi{border:1px solid var(--line);border-radius:13px;background:#fffdf8;padding:14px}.kpi b{display:block;font:800 26px Georgia,serif}.kpi span{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{padding:9px 8px;border-bottom:1px solid #e7ddcd;text-align:left;font-size:12px;vertical-align:middle}th{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)}.num{text-align:right}.table{overflow:auto}.teamgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.team{border:1px solid var(--line);border-radius:12px;background:#fffdf8;padding:12px}.match{display:grid;grid-template-columns:70px 1fr 40px 1fr 190px;gap:8px;align-items:center;border:1px solid var(--line);border-radius:11px;background:#fffdf8;padding:9px;margin-bottom:7px}.score{width:58px;text-align:center}.notice{padding:12px;border:1px solid #dbc8ab;background:#efe3cf;border-radius:10px;font-size:12px;line-height:1.5}.error{background:#f4dfdc;border-color:#dfbdb7;color:#7b291f}.ok{background:#e3ebe4;border-color:#c6d7ca;color:#214331}.empty{text-align:center;padding:24px;border:1px dashed #cdbfa9;border-radius:11px;color:var(--muted)}@media(max-width:900px){.s8,.s7,.s6,.s5,.s4{grid-column:span 12}.kpis,.teamgrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.topin{align-items:flex-start;flex-direction:column}.kpis,.teamgrid{grid-template-columns:1fr}.match{grid-template-columns:1fr}.wrap{padding-left:12px;padding-right:12px}}
</style>
</head>
<body>
<header class="top"><div class="topin"><div class="brand">FOURBAG<small>Venue League Operations</small></div><div class="row"><input class="key" id="operatorKey" type="password" placeholder="Operator key"><button class="btn" id="saveKey">Save Key</button><select id="seasonSelect"></select><button class="btn green" id="refresh">Refresh</button></div></div></header>
<main class="wrap">
<div id="message" style="margin-bottom:12px"></div>
<div class="grid">
<section class="card"><div class="split"><div><h3>Season</h3><h1 id="seasonTitle">Choose a league season</h1><div class="small muted" id="seasonMeta"></div></div><span class="badge green" id="seasonStatus">—</span></div><div class="kpis" style="margin-top:14px"><div class="kpi"><b id="registered">0</b><span>Registered Players</span></div><div class="kpi"><b id="capacity">0</b><span>Capacity</span></div><div class="kpi"><b id="boardBuyers">0</b><span>Board Buyers</span></div><div class="kpi"><b id="teamCount">0</b><span>Teams</span></div></div></section>
<section class="card s4"><h3>League Controls</h3><h2>Build + Schedule</h2><div class="row"><button class="btn red" id="buildTeams">Build Teams</button><button class="btn green" id="generateSchedule">Generate Schedule</button></div><div class="notice" style="margin-top:12px">Team building keeps requested friend/team groups together where capacity allows. The round robin requires every team to be full.</div></section>
<section class="card s8"><h3>Roster</h3><h2>Players</h2><div class="table"><table><thead><tr><th>Player</th><th>Join</th><th>Requested Group</th><th>Team</th><th>FourBag</th><th>Payment</th></tr></thead><tbody id="rosterBody"></tbody></table></div></section>
<section class="card s5"><h3>Teams</h3><h2>Team Builder Result</h2><div id="teams" class="teamgrid"></div></section>
<section class="card s7"><div class="split"><div><h3>Standings</h3><h2>Regular Season</h2></div><button class="btn red" id="championship">Seed Week 8 Championship</button></div><div class="table"><table><thead><tr><th>#</th><th>Team</th><th class="num">P</th><th class="num">W</th><th class="num">L</th><th class="num">PF</th><th class="num">PA</th><th class="num">Diff</th></tr></thead><tbody id="standingsBody"></tbody></table></div></section>
<section class="card"><h3>Schedule + Scoring</h3><h2>Match Operations</h2><div id="schedule"></div></section>
</div>
</main>
<script>
const $=id=>document.getElementById(id);let current=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function key(){return sessionStorage.getItem('fourbagOperatorKey')||$('operatorKey').value.trim()}
function tell(text,type='ok'){$('message').innerHTML=text?`<div class="notice ${type}">${esc(text)}</div>`:''}
async function api(action,{method='GET',body=null,protect=false,query={}}={}){const qs=new URLSearchParams({action,...query});const headers={'Accept':'application/json'};if(body)headers['Content-Type']='application/json';if(protect)headers['X-FourBag-Operator-Key']=key();const r=await fetch(`api.php?${qs}`,{method,headers,body:body?JSON.stringify(body):null});const j=await r.json();if(!j.ok)throw new Error(j.error||'Request failed');return j.data}
async function loadSeasons(){try{const seasons=await api('seasons');$('seasonSelect').innerHTML=seasons.map(s=>`<option value="${s.id}">${esc(s.venue_name)} — ${esc(s.name)}</option>`).join('');if(seasons.length){current=Number($('seasonSelect').value);await loadOps()}}catch(e){tell(e.message,'error')}}
async function loadOps(){if(!current)return;try{const d=await api('operations',{protect:true,query:{season_id:current}});render(d);tell('')}catch(e){tell(e.message,'error')}}
function render(d){$('seasonTitle').textContent=`${d.season.name}`;$('seasonMeta').textContent=`${d.season.start_date} • ${d.season.weeks} weeks • ${d.season.board_count} boards • ${d.season.players_per_team} players/team`;$('seasonStatus').textContent=d.season.status;$('registered').textContent=d.registered_players;$('capacity').textContent=d.capacity;$('boardBuyers').textContent=d.board_buyers;$('teamCount').textContent=d.teams.length;
$('rosterBody').innerHTML=d.roster.length?d.roster.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.email)}</div></td><td>${esc(p.join_type)}</td><td>${esc(p.requested_group||'—')}</td><td>${esc(p.team_name||'Unassigned')}</td><td>${Number(p.board_purchase)?'<span class="badge green">Purchased</span>':'—'}</td><td>${esc(p.payment_status)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No registrations yet.</div></td></tr>';
$('teams').innerHTML=d.teams.length?d.teams.map(t=>`<div class="team"><strong>${esc(t.name)}</strong><div class="small muted">${t.player_count}/${d.season.players_per_team} players • ${esc(t.status)}</div></div>`).join(''):'<div class="empty" style="grid-column:1/-1">Build teams after players register.</div>';
$('standingsBody').innerHTML=d.standings.length?d.standings.map(s=>`<tr><td>${s.rank}</td><td><strong>${esc(s.team_name)}</strong></td><td class="num">${s.played}</td><td class="num">${s.wins}</td><td class="num">${s.losses}</td><td class="num">${s.points_for}</td><td class="num">${s.points_against}</td><td class="num">${s.differential>0?'+':''}${s.differential}</td></tr>`).join(''):'<tr><td colspan="8"><div class="empty">No teams yet.</div></td></tr>';
renderSchedule(d.schedule)}
function renderSchedule(matches){if(!matches.length){$('schedule').innerHTML='<div class="empty">Generate the round robin after teams are full.</div>';return}const weeks={};for(const m of matches)(weeks[m.week_no]??=[]).push(m);$('schedule').innerHTML=Object.entries(weeks).map(([week,ms])=>`<div style="margin-bottom:18px"><div class="split" style="margin-bottom:8px"><strong>Week ${week}</strong><span class="badge ${ms.some(x=>x.stage!=='regular')?'red':''}">${ms.some(x=>x.stage!=='regular')?'Championship':'Round Robin'}</span></div>${ms.map(m=>`<div class="match"><span class="badge">${esc(m.stage)} • B${m.board_no}</span><strong>${esc(m.home_team||'TBD')}</strong><span>vs</span><strong>${esc(m.away_team||'TBD')}</strong><span class="row"><input class="score" id="h${m.id}" type="number" min="0" value="${m.home_score??''}" ${!m.home_team_id?'disabled':''}><input class="score" id="a${m.id}" type="number" min="0" value="${m.away_score??''}" ${!m.away_team_id?'disabled':''}><select id="s${m.id}" ${!m.home_team_id||!m.away_team_id?'disabled':''}><option value="final" ${m.status==='final'?'selected':''}>Final</option><option value="live" ${m.status==='live'?'selected':''}>Live</option></select><button class="btn" onclick="score(${m.id})" ${!m.home_team_id||!m.away_team_id?'disabled':''}>Save</button></span></div>`).join('')}</div>`).join('')}
async function action(name,body){try{await api(name,{method:'POST',body,protect:true});await loadOps();tell('Saved.')}catch(e){tell(e.message,'error')}}
async function score(id){const h=$(`h${id}`).value,a=$(`a${id}`).value;if(h===''||a===''){tell('Enter both scores.','error');return}await action('score.record',{match_id:id,home_score:Number(h),away_score:Number(a),status:$(`s${id}`).value,recorded_by:'venue-operator'})}
$('saveKey').onclick=()=>{sessionStorage.setItem('fourbagOperatorKey',$('operatorKey').value.trim());tell('Operator key saved for this browser tab.');loadOps()};$('refresh').onclick=loadOps;$('seasonSelect').onchange=()=>{current=Number($('seasonSelect').value);loadOps()};$('buildTeams').onclick=()=>action('teams.build',{season_id:current});$('generateSchedule').onclick=()=>action('schedule.generate',{season_id:current});$('championship').onclick=()=>action('championship.create',{season_id:current});$('operatorKey').value=sessionStorage.getItem('fourbagOperatorKey')||'';loadSeasons();
</script>
</body>
</html>
